set -euo pipefail
python3 - <<'PY'
import json, pathlib, sqlite3, os
r=pathlib.Path('/workspace/omega_runtime'); state=r/'state'; db=r/'data'/'omega_unified.db'
out={'current':str((r/'current').resolve()),'lock':(state/'omega-supervisor.lock').read_text().strip() if (state/'omega-supervisor.lock').exists() else None}
if (state/'SUPERVISOR_STATUS.json').exists(): out['status']=json.loads((state/'SUPERVISOR_STATUS.json').read_text())
if db.exists():
 c=sqlite3.connect(f'file:{db}?mode=ro',uri=True); c.row_factory=sqlite3.Row
 try:
  if c.execute("select 1 from sqlite_master where type='table' and name='relay_ledger'").fetchone():
   out['relay_states']={r['state']:r['n'] for r in c.execute('select state,count(*) n from relay_ledger group by state')}
   out['active_relay']=[dict(x) for x in c.execute("select effect_id,organ_id,state,updated_at from relay_ledger where state in ('DISPATCHING','UNKNOWN') order by updated_at")]
 finally: c.close()
print(json.dumps(out,sort_keys=True))
PY
